     3→import { exec } from "child_process";
     4→import { promisify } from "util";
     5→
     6→const execAsync = promisify(exec);
     7→
     8→export interface ProjectInfo {
     9→  projectDir: string;
    10→  projectName: string;
    11→  agentCount: number;
    12→  activeCount: number;
    13→  lastActivity: Date;
    14→  sessions: ProjectSession[];
    15→}
    16→
    17→export interface ProjectSession {
    18→  sessionId: string;
    19→  projectDir: string;
    20→  jsonlFile: string;
    21→  isActive: boolean;
    22→  lastModified: Date;
    23→}
    24→
    25→export interface ClaudeProcess {
    26→  pid: number;
    27→  cwd: string;
    28→}
    29→
    30→const CLAUDE_DIR = path.join(process.env.HOME || "", ".claude");
    31→const PROJECTS_DIR = path.join(CLAUDE_DIR, "projects");
    32→
    33→class ProjectDiscoveryService {
    34→  /**
    35→   * 将编码的目录名转换为真实路径
    36→   * e.g. "-Users-yangsmac-Desktop-Slack" → "/Users/yangsmac/Desktop/Slack"
    37→   * e.g. "-Users-yangsmac-Desktop-claude-skills-and-agents-manager" → "/Users/yangsmac/Desktop/claude-skills-and-agents-manager"
    38→   */
    39→  private decodeDirName(encoded: string): string {
    40→    // Claude Code 的编码规则：用 "-" 替换每个 "/"，开头保留 "-"
    41→    // 问题：目录名中的 "-" 也会被保留，导致无法简单解码
    42→    // 解决方案：使用启发式方法，从最简单的情况开始尝试，直到找到存在的路径
    43→
    44→    // 1. 先尝试简单替换所有 "-" 为 "/"
    45→    let decoded = encoded.replace(/-/g, "/").replace(/\/+/g, "/");
    46→
    47→    // 2. 检查路径是否存在，如果存在就返回
    48→    if (fs.existsSync(decoded)) {
    49→      return decoded;
