    95→      return "bg-green-500/5 border border-green-500/30 hover:border-green-500/50";
    96→    }
    97→    return "bg-card border border-border hover:border-primary/30";
    98→  };
    99→
   100→  return (
   101→    <div className="space-y-3">
   102→      {/* 标题和Batch操作工具栏 */}
   103→      <div className="flex items-center justify-between pb-2 border-b border-border">
   104→        <div className="flex items-center gap-2">
   105→          {title && <h2 className="font-semibold">{title}</h2>}
   106→          {onBatchDelete && (
   107→            <button
   108→              className={`flex items-center gap-1 text-sm px-2 py-1 rounded ${
   109→                isBatchMode ? "text-primary bg-primary/10" : "text-muted-foreground hover:text-foreground"
   110→              }`}
   111→              onClick={() => {
