    24→  ]);
    25→  const [model, setModel] = useState("sonnet");
    26→  const [body, setBody] = useState("");
    27→  const [loading, setLoading] = useState(!isNew);
    28→  const [saving, setSaving] = useState(false);
    29→  const [isPlugin, setIsPlugin] = useState(false);
    30→  const [showTerminal, setShowTerminal] = useState(false);
    31→  const [isRunning, setIsRunning] = useState(false);
    32→
    33→  useEffect(() => {
    34→    if (!isNew && name) {
    35→      window.electronAPI.agents.read(name).then((agent) => {
    36→        if (agent) {
    37→          setFormName(agent.name);
    38→          setDescription(agent.description);
    39→          setTools(agent.tools);
    40→          setModel(agent.model);
    41→          setBody(agent.body);
    42→          setIsPlugin(agent.source === "plugin");
    43→        }
    44→        setLoading(false);
    45→      });
    46→    }
    47→  }, [name, isNew]);
    48→
    49→  const handleSave = async (): Promise<void> => {
    50→    if (!formName.trim()) return;
    51→    setSaving(true);
    52→    try {
    53→      const fileName = isNew
    54→        ? formName.trim().toLowerCase().replace(/\s+/g, "-")
    55→        : name!;
    56→      await window.electronAPI.agents.write(fileName, {
    57→        name: formName.trim(),
    58→        description,
    59→        tools,
    60→        model,
    61→        body,
    62→      });
    63→      navigate("/agents");
    64→    } finally {
    65→      setSaving(false);
    66→    }
    67→  };
    68→
    69→  const handleDelete = async (): Promise<void> => {
    70→    if (!name || isNew) return;
    71→    if (!confirm(t("agents.deleteConfirm", { name: name || "" }))) return;
    72→    await window.electronAPI.agents.delete(name);
    73→    navigate("/agents");
    74→  };
