     5→export async function POST(request: NextRequest) {
     6→  try {
     7→    const { prompt, config } = await request.json();
     8→
     9→    if (!prompt) {
    10→      return new Response(JSON.stringify({ error: 'Prompt is required' }), {
    11→        status: 400,
    12→        headers: { 'Content-Type': 'application/json' },
    13→      });
    14→    }
    15→
    16→    // 创建一个 ReadableStream 用于流式响应
    17→    const stream = new ReadableStream({
    18→      async start(controller) {
    19→        const encoder = new TextEncoder();
    20→
    21→        try {
    22→          // 构建 Agent SDK 配置，使用传入的 config 或默认值
    23→          const agentOptions: any = {
    24→            model: config?.model || 'sonnet',
    25→            cwd: config?.cwd
    26→              ? path.join(process.cwd(), config.cwd)
    27→              : path.join(process.cwd(), 'public', 'uploads'),
    28→            allowedTools: config?.allowedTools || ['Read', 'Glob', 'Grep', 'Write', 'Edit', 'Bash'],
    29→            // 🔧 在 API 路由中必须使用非交互式权限模式
    30→            // "ask" 模式会导致进程退出，因为无法弹出对话框
    31→            dangerouslySkipPermissions: true,
    32→          };
    33→
    34→          // ⚠️ 忽略用户传入的 permissionMode，因为在 API 路由中不支持交互式权限
    35→          // 如果需要权限控制，应该在 allowedTools 中限制工具列表
    36→
    37→          // 只有在明确设置时才添加 systemPrompt
    38→          if (config?.systemPrompt) {
    39→            agentOptions.systemPrompt = config.systemPrompt;
    40→          }
    41→
    42→          // 🔍 调试日志：显示 Agent SDK 配置
    43→          console.log('🚀 Starting Agent SDK with config:');
    44→          console.log('Prompt:', prompt);
